/**
 * Counts unique words (case-insensitive).
 * "hello world hello" → 2
 */
export function countUniqueWords(str: string): number {
  const trimmed = str.trim();
  if (!trimmed) return 0;
  const words = trimmed.split(/\s+/).map((w) => w.toLowerCase());
  return new Set(words).size;
}

